import{_ as l,W as i,s as o,u as r,I as e,ah as d,w as a,Z as t,A as p}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const C=JSON.parse('{"title":"给 “rm” 命令添加个“垃圾桶” | LCTT x X-CMD","titleTemplate":false,"description":"给 “rm” 命令添加个“垃圾桶” | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"给 “rm” 命令添加个“垃圾桶” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"给 “rm” 命令添加个“垃圾桶” | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171016 Make -rm- Command To Move The Files To -Trash Can- Instead Of Removing Them Completely","title":"给 “rm” 命令添加个“垃圾桶”","tag":"201803"},"relativePath":"201803/20171016 Make -rm- Command To Move The Files To -Trash Can- Instead Of Removing Them Completely.md","filePath":"[post].md"}'),m={name:"201803/20171016 Make -rm- Command To Move The Files To -Trash Can- Instead Of Removing Them Completely.md"};function h(u,s,c,g,f,v){const n=i("Link");return r(),o("div",null,[s[18]||(s[18]=e("h1",{id:"给-rm-命令添加个-垃圾桶",tabindex:"-1"},[a("给 “rm” 命令添加个“垃圾桶” "),e("a",{class:"header-anchor",href:"#给-rm-命令添加个-垃圾桶","aria-label":"Permalink to 给 “rm” 命令添加个“垃圾桶”"},"​")],-1)),s[19]||(s[19]=e("p",null,[a("人类犯错误是因为我们不是一个可编程设备，所以，在使用 "),e("code",null,"rm"),a(" 命令时要额外注意，不要在任何时候使用 "),e("code",null,"rm -rf *"),a("。当你使用 "),e("code",null,"rm"),a(" 命令时，它会永久删除文件，不会像文件管理器那样将这些文件移动到 “垃圾箱”。")],-1)),s[20]||(s[20]=e("p",null,"有时我们会将不应该删除的文件删除掉，所以当错误地删除了文件时该怎么办？ 你必须看看恢复工具（Linux 中有很多数据恢复工具），但我们不知道是否能将它百分之百恢复，所以要如何解决这个问题？",-1)),e("p",null,[s[2]||(s[2]=a("我们最近发表了一篇关于 ")),t(n,{href:"https://www.2daygeek.com/trash-cli-command-line-trashcan-linux-system/"},{default:p(()=>s[0]||(s[0]=[a("Trash-Cli")])),_:1}),s[3]||(s[3]=a(" 的文章，在评论部分，我们从用户 Eemil Lgz 那里获得了一个关于 ")),t(n,{href:"https://github.com/lagerspetz/linux-stuff/blob/master/scripts/saferm.sh"},{default:p(()=>s[1]||(s[1]=[a("saferm.sh")])),_:1}),s[4]||(s[4]=a(" 脚本的更新，它可以帮助我们将文件移动到“垃圾箱”而不是永久删除它们。"))]),s[21]||(s[21]=d(`<p>将文件移动到“垃圾桶”是一个好主意，当你无意中运行 <code>rm</code> 命令时，可以拯救你；但是很少有人会说这是一个坏习惯，如果你不注意“垃圾桶”，它可能会在一定的时间内被文件和文件夹堆积起来。在这种情况下，我建议你按照你的意愿去做一个定时任务。</p><p>这适用于服务器和桌面两种环境。 如果脚本检测到 GNOME 、KDE、Unity 或 LXDE 桌面环境（DE），则它将文件或文件夹安全地移动到默认垃圾箱 <code>$HOME/.local/share/Trash/files</code>，否则会在您的主目录中创建垃圾箱文件夹 <code>$HOME/Trash</code>。</p><p><code>saferm.sh</code> 脚本托管在 Github 中，可以从仓库中克隆，也可以创建一个名为 <code>saferm.sh</code> 的文件并复制其上的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone https://github.com/lagerspetz/linux-stuff</span></span>
<span class="line"><span>$ sudo mv linux-stuff/scripts/saferm.sh /bin</span></span>
<span class="line"><span>$ rm -Rf linux-stuff</span></span></code></pre></div><p>在 <code>.bashrc</code> 文件中设置别名，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alias rm=saferm.sh</span></span></code></pre></div><p>执行下面的命令使其生效，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>一切就绪，现在你可以执行 <code>rm</code> 命令，自动将文件移动到”垃圾桶”，而不是永久删除它们。</p><p>测试一下，我们将删除一个名为 <code>magi.txt</code> 的文件，命令行明确的提醒了 <code>Moving magi.txt to $HOME/.local/share/Trash/file</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rm -rf magi.txt</span></span>
<span class="line"><span>Moving magi.txt to /home/magi/.local/share/Trash/files</span></span></code></pre></div><p>也可以通过 <code>ls</code> 命令或 <code>trash-cli</code> 进行验证。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls -lh /home/magi/.local/share/Trash/files</span></span>
<span class="line"><span>Permissions Size User Date Modified Name</span></span>
<span class="line"><span>.rw-r--r-- 32 magi 11 Oct 16:24 magi.txt</span></span></code></pre></div><p>或者我们可以通过文件管理器界面中查看相同的内容。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2017/10/rm-command-to-move-files-to-trash-can-rm-alias-1.png" alt=""></p><p>（LCTT 译注：原文此处混淆了部分 trash-cli 的内容，考虑到文章衔接和逻辑，此处略。）</p><p>要了解 <code>saferm.sh</code> 的其他选项，请查看帮助。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ saferm.sh -h</span></span>
<span class="line"><span>This is saferm.sh 1.16. LXDE and Gnome3 detection.</span></span>
<span class="line"><span>Will ask to unsafe-delete instead of cross-fs move. Allows unsafe (regular rm) delete (ignores trashinfo).</span></span>
<span class="line"><span>Creates trash and trashinfo directories if they do not exist. Handles symbolic link deletion.</span></span>
<span class="line"><span>Does not complain about different user any more.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: /path/to/saferm.sh [OPTIONS] [--] files and dirs to safely remove</span></span>
<span class="line"><span>OPTIONS:</span></span>
<span class="line"><span>-r      allows recursively removing directories.</span></span>
<span class="line"><span>-f      Allow deleting special files (devices, ...).</span></span>
<span class="line"><span>-u      Unsafe mode, bypass trash and delete files permanently.</span></span>
<span class="line"><span>-v      Verbose, prints more messages. Default in this version.</span></span>
<span class="line"><span>-q      Quiet mode. Opposite of verbose.</span></span></code></pre></div><hr>`,19)),e("p",null,[s[6]||(s[6]=a("via: ")),t(n,{href:"https://www.2daygeek.com/rm-command-to-move-files-to-trash-can-rm-alias/"},{default:p(()=>s[5]||(s[5]=[a("https://www.2daygeek.com/rm-command-to-move-files-to-trash-can-rm-alias/")])),_:1})]),e("p",null,[s[10]||(s[10]=a("作者：")),t(n,{href:"https://www.2daygeek.com/author/2daygeek/"},{default:p(()=>s[7]||(s[7]=[a("2DAYGEEK")])),_:1}),s[11]||(s[11]=a(" 译者：")),t(n,{href:"https://github.com/amwps290"},{default:p(()=>s[8]||(s[8]=[a("amwps290")])),_:1}),s[12]||(s[12]=a(" 校对：")),t(n,{href:"https://github.com/wxy"},{default:p(()=>s[9]||(s[9]=[a("wxy")])),_:1})]),e("p",null,[s[15]||(s[15]=a("本文由 ")),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[13]||(s[13]=[a("LCTT")])),_:1}),s[16]||(s[16]=a(" 原创编译，")),t(n,{href:"https://linux.cn/"},{default:p(()=>s[14]||(s[14]=[a("Linux中国")])),_:1}),s[17]||(s[17]=a(" 荣誉推出"))])])}const k=l(m,[["render",h]]);export{C as __pageData,k as default};
